@ApiOperation("实名认证")
    @PostMapping(value = "realNameAuthentication", produces = MediaType.APPLICATION_JSON_VALUE)
    public GenericResponse authorization(@PathVariable("channelSource") String channelSource, @Valid @RequestBody AuthorizationDTO authorizationDTO) {
        String userId = SecurityUtil.obtainUserId();
        log.info("realNameAuthentication with authorizationDTO is {} and userId is {}", authorizationDTO, userId);

        try {
            authorizationDTO.setUserId(userId);
            userService.supplyBaseInfo(authorizationDTO);
            return GenericResponse.success(true);
        } catch (Exception e) {
            log.warn("realNameAuthentication encountered exception, with authorizationDTO is {}.", authorizationDTO, e);
            return GenericResponse.fail(e.getMessage());
        }
    }

